/* Addresses live only in memory. No analytics or local storage. */
window.AddressPlanner=(()=>{
 const $=id=>document.getElementById(id),E=window.ScheduleEngine;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const clock=n=>{const day=Math.floor(n/1440),v=(n%1440+1440)%1440,h=Math.floor(v/60);return `${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][((day%7)+7)%7]} ${h%12||12}:${String(v%60).padStart(2,'0')} ${h<12?'am':'pm'}`};
 let update,context='',office='',values=['','','',''],source='manual',message='',ready=false,loading=false;
 const maps=(a,b)=>'https://www.google.com/maps/dir/?'+new URLSearchParams({api:'1',origin:a,destination:b,travelmode:$('mode').value});
 function init(fn){update=fn;fetch('/api/status').then(r=>r.json()).then(r=>{ready=r.routing;update();}).catch(()=>{});}
 function render(s){const setup=$('routeSetup'),home=$('home').value.trim(),work=$('work').value.trim();
 if(!home||!work){setup.hidden=true;return false;}
 setup.hidden=false;const rows=window.SCHEDULE_DATA.records.filter(r=>r.service===$('service').value&&($('borough').value==='all'||r.borough===$('borough').value||r.borough==='Citywide'));
 if(!rows.some(r=>r.id===office))office=rows[0]?.id||'';
 const r=rows.find(r=>r.id===office);const key=[home,work,office,$('mode').value].join('|');if(key!==context){context=key;values=['','','',''];source='manual';message='';}
 const selectedDay=setup.querySelector('#routeDay')?.value??String(s.days[0]??0);
 const date=setup.querySelector('#routeDate')?.value||new Date(Date.now()+86400000).toLocaleDateString('en-CA');
 const at=setup.querySelector('#routeTime')?.value||'08:00';
 setup.innerHTML=`<div class="route-head"><h2>03 <span>Find a way there</span></h2><label>Office / channel<select id="office">${rows.map(x=>`<option value="${esc(x.id)}" ${x.id===office?'selected':''}>${esc(x.name)} · ${esc(x.borough)}</option>`).join('')}</select></label><label>Shift starts on<select id="routeDay">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((d,i)=>`<option value="${i}" ${String(i)===selectedDay?'selected':''}>${d}</option>`).join('')}</select></label></div>`;
 if(!r){$('result').innerHTML='<p>No matching offices in this inventory. Try another borough.</p>';bind();return true;}
 if(r.channel!=='in_person'){const p=E.planVisit(r,s);$('result').innerHTML=`<div class="outcome"><p class="eyebrow">REMOTE APPOINTMENT · NO TRAVEL</p><h3>${p.kind==='fits'?'No work overlap':p.kind==='overlap'?p.overlap+' minutes overlap':p.kind==='closed'?'Listed closed':'No verified window'}</h3><p>${esc(r.hoursText)}</p><p>${esc(r.remoteAlternative||'')}</p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">Official instructions ↗</a></div>`;bind();return true;}
 const address=r.address?`${r.address}, ${r.borough}, NY`:'';
 if(!address){$('result').innerHTML='<p>No verified street address for this listing. Check its official instructions.</p>';bind();return true;}
 const legs=[[home,address,'Home → office'],[address,work,'Office → work'],[work,address,'Work → office'],[address,home,'Office → home']];
 setup.innerHTML+=`<p class="small">${esc(address)} · <a href="https://www.google.com/maps/search/?${new URLSearchParams({api:'1',query:address})}" target="_blank" rel="noopener noreferrer">See office on map ↗</a></p><div class="leg-grid">${legs.map((l,i)=>`<div><a href="${esc(maps(l[0],l[1]))}" target="_blank" rel="noopener noreferrer">${l[2]} ↗</a><label>Travel minutes<input id="leg${i}" type="number" min="0" max="600" step="1" placeholder="—" value="${values[i]}"></label></div>`).join('')}</div><p class="small">${ready?'Google Maps estimates available.':'Automatic travel estimates aren’t connected yet.'} Open each route in Google Maps and enter its travel time. Choose the appointment day and time in Maps; routes change throughout the day.</p>${ready?`<div class="care"><label>Estimate date<input id="routeDate" type="date" value="${date}"></label><label>Departure time (New York)<input id="routeTime" type="time" value="${at}"></label><button id="fetchRoutes" ${loading?'disabled':''}>${loading?'Finding routes…':'Get Google Maps estimates'}</button></div>`:''}<p class="small" role="status">${esc(message)}</p>`;
 const day=Number(selectedDay),num=i=>values[i]===''?NaN:Number(values[i]);
 const variants=[['before','Before work','Home → office → work',0,1],['during','During work','Work → office → work',2,1],['after','After work','Work → office → home',2,3]];
 $('result').innerHTML=`<div class="route-results">${variants.map(([kind,title,path,a,b])=>{const p=E.routeVisit(r,s,day,kind,num(a),num(b));const possible=['fits','overlap'].includes(p.kind);return `<article class="route-card ${p.kind==='fits'?'fit':''}"><p class="eyebrow">${title}</p><div class="route-path">${path}</div><h3>${possible?(p.overlap?`${p.overlap} min`:'No overlap'):p.kind==='missing'?'Add travel times':p.kind==='unknown'?'Hours unverified':p.kind==='closed'?'Listed closed':p.kind==='dayoff'?'Your day off':'No modeled window'}</h3><p class="small">${possible?(p.overlap?'of work time overlaps this plan.':'with your selected shift.'):p.kind==='dayoff'?'Choose one of your workdays to compare these routes.':'Check your inputs and the published schedule.'}</p>${possible?`<ol><li>Leave ${kind==='before'?'home':'work'} <strong>${clock(p.depart)}</strong></li><li>Office <strong>${clock(p.start)}–${clock(p.finish)}</strong></li><li>Reach ${kind==='after'?'home':'work'} <strong>${clock(p.back)}</strong></li></ol>`:''}</article>`;}).join('')}</div><p class="small">${source==='manual'?'Using travel times you entered.':'Travel estimates by Google Maps, sampled at one departure time; not verified for every window above.'} Appointment: ${s.duration} min · waiting: ${s.wait?s.wait+' min':'not included'}. This compares one office, not the nearest or fastest office. ${r.scheduleExceptions?.length?'Special-date hours are not modeled.':''}</p><details class="route" open><summary>Can I skip the trip?</summary><p>${esc(r.remoteAlternative||'An online alternative has not been verified for this record.')}</p><p>${esc(r.appointment||'')}</p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">Official instructions ↗</a></details><details class="route"><summary>Published hours & conditions</summary><p>${esc(r.hoursText)}</p><p>${esc(r.notes||'')}</p><p>${esc(r.exceptionsText||'')}</p></details>`;
 bind();
 for(const id of ['routeDate','routeTime'])if($(id))$(id).onchange=()=>{values=['','','',''];source='manual';message='Travel times cleared for the new reference time.';update();};
 for(let i=0;i<4;i++)$('leg'+i).onchange=()=>{const input=$('leg'+i);values[i]=input.validity.valid?input.value:'';source='manual';update();};
 if($('fetchRoutes'))$('fetchRoutes').onclick=async()=>{const requestContext=context;loading=true;message='';const payload={legs:legs.map(l=>({origin:l[0],destination:l[1]})),mode:$('mode').value,date:$('routeDate').value,time:$('routeTime').value};update();try{const response=await fetch('/api/routes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw Error(data.error||'Route lookup failed.');if(context===requestContext){values=data.minutes.map(n=>n===null?'':String(n));source='google';message='Estimates by Google Maps. Recheck each leg for your actual appointment time.';}}catch(e){if(context===requestContext)message=e.message;}finally{loading=false;update();}};
 return true;
 }
 function bind(){$('office').onchange=()=>{office=$('office').value;update();};$('routeDay').onchange=update;}
 return {init,render};
})();
